G3D::Rect2D GuiItem::getMyRect2D() const
{
	G3D::Vector2 p = getPosition();
	G3D::Vector2 s = getSize();
	return G3D::Rect2D(p, p + s);   // the two Vector2 temporaries are built at [esp+0x14] and [esp+0x1c]
}
